spec.expr:
label_set(
  avg(
    topk(
      30,
      last_over_time(pvEnergyDaily[$__range])
    ) by(year)
  ) by(year),
  "period",
  "total"
)

(
  (
    label_set(
      sum(
        last_over_time(
          energyPriceBoughtDaily[$__range]
        )
      ) by(month),
      "series",
      "purchased"
    )
      or
    label_set(
      0
        -
      sum(
        last_over_time(
          energyPriceSoldDaily[$__range]
        )
      ) by(month),
      "series",
      "sold"
    )
  )
    or
  label_set(
    clamp_min(
      sum(
        last_over_time(
          energyPriceBoughtDaily[$__range]
        )
      ) by(month)
        -
      sum(
        last_over_time(
          energyPriceSoldDaily[$__range]
        )
      ) by(month),
      0
    ),
    "series",
    "costs"
  )
)
  or
label_set(
  clamp_max(
    sum(
      last_over_time(
        energyPriceBoughtDaily[$__range]
      )
    ) by(month)
      -
    sum(
      last_over_time(
        energyPriceSoldDaily[$__range]
      )
    ) by(month),
    0
  ),
  "series",
  "profit"
)
